/*
 * Timeline chart
 *
 * wt-chart, wt-chart-timeline
 */
#timeline_chart {
    position: relative;
    top: 0;
    left: 0;
}
.person0, .person1, .person2, .person3,
.person4, .person5, .person6, .person7 {
    --person-bg-alpha: 30%;
}
.person0 {
    background-color: color-mix(in srgb, var(--bs-red) var(--person-bg-alpha), transparent);
}
.person1 {
    background-color: color-mix(in srgb, var(--bs-orange) var(--person-bg-alpha), transparent);
}
.person2 {
    background-color: color-mix(in srgb, var(--bs-yellow) var(--person-bg-alpha), transparent);
}
.person3 {
    background-color: color-mix(in srgb, var(--bs-green) var(--person-bg-alpha), transparent);
}
.person4 {
    background-color: color-mix(in srgb, var(--bs-teal) var(--person-bg-alpha), transparent);
}
.person5 {
    background-color: color-mix(in srgb, var(--bs-cyan) var(--person-bg-alpha), transparent);
}
.person6 {
    background-color: color-mix(in srgb, var(--bs-purple) var(--person-bg-alpha), transparent);
}
.person7 {
    background-color: color-mix(in srgb, var(--bs-pink) var(--person-bg-alpha), transparent);
}
/* Lines for "vertical" charts, such as the ancestors and descendants chart. */
.wt-chart-horizontal-indent {
    width: 3rem;
}
.wt-chart-vertical-line {
    width: 50%;
    height: 100%;
    right: 0;
    border-left: var(--chart-line);
}
.wt-chart-vertical-last-child-line {
    width: 50%;
    right: 0;
    height: 2.5rem;
    top: 0;
    border-left: var(--chart-line);
    border-bottom: var(--chart-line);
    border-radius: 0 0 0 var(--chart-line-radius);
}
.wt-chart-vertical-child-line {
    width: 50%;
    right: 0;
    height: 2.5rem;
    top: 0;
    border-bottom: var(--chart-line);
}
/* Lines for horizontal trees, such as the family page */
.wt-chart-horizontal-spacer {
    width: 1rem;
}
.wt-chart-horizontal-line {
    width: 1rem;
    height: 50%;
    border-bottom: var(--chart-line);
}
.wt-chart-horizontal-first-child {
    height: 50%;
    position: relative;
    top: 50%;
    border-top: var(--chart-line);
    border-right: var(--chart-line);
    border-radius: 0 var(--chart-line-radius) 0 0;
}
.wt-chart-horizontal-middle-child {
    height: 100%;
    border-right: var(--chart-line);
}
.wt-chart-horizontal-last-child {
    height: 50%;
    border-bottom: var(--chart-line);
    border-right: var(--chart-line);
    border-radius: 0 0 var(--chart-line-radius) 0;
}
.wt-chart-horizontal-first-parent {
    height: 50%;
    position: relative;
    top: 50%;
    border-top: var(--chart-line);
    border-left: var(--chart-line);
    border-radius: var(--chart-line-radius) 0 0 0;
}
.wt-chart-horizontal-last-parent {
    height: 50%;
    border-bottom: var(--chart-line);
    border-left: var(--chart-line);
    border-radius: 0 0 0 var(--chart-line-radius);
}
/* Buttons to expand/collapse other parts of the chart */
.wt-chart-expansion-control > .chart-expand {
    display: none;
}
.wt-chart-expansion-control > .chart-collapse {
    display: inline;
}
.wt-chart-expansion-control.collapsed > .chart-expand {
    display: inline;
}
.wt-chart-expansion-control.collapsed > .chart-collapse {
    display: none;
}
.wt-chart-box-name {
    font-weight: bold;
}
