/*
 * http://www.jacklmoore.com/colorbox
 *
 * #cboxOverlay
 * #cboxLoadingOverlay
 * #cboxLoadingGraphic
 * #colorbox
 * +----#cboxWrapper
 *      +----<div>
 *      |    +----#cboxTopLeft
 *      |    +----#cboxTopCentre
 *      |    +----#cboxTopRight
 *      +----<div>
 *      |    +----#cboxMiddleLeft
 *      |    +----#cboxContent
 *      |    |    +----#cboxLoadedContent
 *      |    |         +----#cboxPhoto
 *      |    |    +----#cboxTitle
 *      |    |    +----#cboxCurrent
 *      |    |    +----#cboxPrevious
 *      |    |    +----#cboxNext
 *      |    |    +----#cboxSlideshow
 *      |    |    +----#cboxLoadingOverlay
 *      |    |    +----#cboxLoadingGraphic
 *      |    |    +----#cboxClose
 *      |    +----cboxMiddleRight
 *      +----<div>
 *           +----#cboxBottomLeft
 *           +----#cboxBottomCenter
 *           +----#cboxBottomRight
 */
#cboxOverlay {
    position: fixed;
    width: 100%;
    height: 100%;
}
#cboxLoadingOverlay,
#cboxLoadingGraphic {
    position: absolute;
    width: 100%;
    height: 100%;
}
#cboxOverlay,
#colorbox {
    z-index: 9999;
}
#cboxContent,
#cboxOverlay {
    background: var(--bs-body-bg);
}
#cboxContent {
    overflow: hidden;
    position: relative;
    padding: 0.5rem;
    border: var(--bs-border-width) var(--bs-border-style) var(--bs-border-color);
    border-radius: var(--bs-border-radius-lg);
    box-sizing: content-box;
}
.cboxPhoto {
    margin: auto;
    display: block;
}
#cboxError {
    padding: 50px;
    border: 1px solid #ccc;
}
#cboxLoadedContent {
    margin-bottom: 28px;
    box-sizing: content-box;
}
#cboxTitle {
    position: absolute;
    bottom: 0.25rem;
    margin: 0 2rem 0 4.5rem;
    text-align: center;
}
#cboxLoadingGraphic {
    background: url(data:image/gif;base64,) no-repeat center center;
}
#cboxPrevious, #cboxNext, #cboxSlideshow, #cboxClose {
    background-color: transparent;
    border: 0;
    border-radius: var(--bs-border-radius);
    color: var(--bs-emphasis-color);
    overflow: visible;
    padding: 0 0.5rem;
    position: absolute;
}
#cboxSlideshow {
    bottom: 0.25rem;
    right: 0.25rem;
}
#cboxPrevious {
    bottom: 0.25rem;
    left: 0.25rem;
}
#cboxNext {
    bottom: 0.25rem;
    left: 2.5rem;
}
#cboxClose {
    top: 0.25rem;
    right: 0.25rem;
}
